  },
  CollectionHall_100458_Title = {
    Text = "Ristoro al Focolare"
  },
  CollectionHall_100459_Desc = {
    Text = "Brucia, brucia, che tutto ciò che è tuo sia consumato dalle fiamme.\nPoi, nel fuoco sconfinato, che abbia inizio il funerale per te e per questo mondo!"
  },
  CollectionHall_100459_LockTip = {
    Text = "Completa l'Immersione Psichica \"Giorno eterno immortale\""
  },
  CollectionHall_100459_Title = {
    Text = "Funerale tra le Fiamme"
  },
  CollectionHall_100460_Desc = {
    Text = "\"Ho giurato di riportare Tutti a casa, con ogni mezzo necessario.\nPerciò brucerò tutto ciò che sono...\n...e con il fuoco karmico delle stelle, purificherò questo mondo falso, immondo e caotico!\nIn nome mio, Kathigu-Ra!\nOra porto l'alba!\""
  },
  CollectionHall_100460_LockTip = {
    Text = "Completa l'Immersione Psichica \"Giorno eterno immortale\""
  },
  CollectionHall_100460_Title = {
    Text = "L'Alba che Brucia Ogni Cosa"
  },
  CollectionHall_100461_Desc = {
    Text = "Il turbinio frenetico in una Frenesia di Caleidoscopio: quel dolce marcio di Peste e cadaveri, il loro sacro profumo.\nAttraverso un mare di dannati, alzi il calice in un brindisi a lei:\nSe la morte è inevitabile, allora danziamo lieti il valzer nel suo Abbraccio; all'ultimo passo della danza, precipiteremo insieme nelle fauci spalancate dell'inferno."
  },
  CollectionHall_100461_LockTip = {
    Text = "Completa l'Immersione Psichica \"Banchetto di Fiamme\" in difficoltà Difficile"
  },
  CollectionHall_100461_Title = {
    Text = "Vino, Fiori e Morte Gloriosa"
  },
  CollectionHall_100462_Desc = {
    Text = "Molto, molto tempo fa, ella era l'unica Monarca dell'universo, e tutto ciò che lo sguardo abbracciava si piegava al suo Dominio.\nMolto, molto tempo dopo, I Suoi Occhi contemplavano soltanto polvere infinita, e tutto ciò che restava nella sua stretta era desolazione e Silenzio."
  },
  CollectionHall_100462_LockTip = {
    Text = "Completa l'Immersione Psichica \"Banchetto di Fiamme\""
  },
  CollectionHall_100462_Title = {
    Text = "Regina della Desolazione"
  },
  CollectionHall_100463_Desc = {
    Text = "È selvaggia, tirannica e volubile. È magnanima, sagace e traboccante di saggezza.\nUna despota depravata, eppure guardiana degli agnelli; elargisce amore e dispensa morte.\nOgni creatura vivente su questa terra deve inginocchiarsi ai suoi piedi, cantando con reverenza il suo nome.\nAnnegati nel ballo della Regina, e poi discendi con lei nelle fiamme nere ed eterne."
  },
  CollectionHall_100463_LockTip = {
    Text = "Completa l'Immersione Psichica \"Banchetto di Fiamme\""
  },
  CollectionHall_100463_Title = {
    Text = "Banchetto in Onore della Morte"
  },
  CollectionHall_100464_Desc = {
    Text = "Se un solo ultimo atto le resta prima della fine, riflette, che sia una danza. Che io svuoti il vino più dolce, banchetti con carni speziate, e danzi vorticando finché il mondo non si dissolva in un dorato Delirium.\nQuesto ella esige: quando il mondo giungerà alla fine, che il suo ultimo riflesso nei suoi occhi sia un lucente velo d'oro."
  },
  CollectionHall_100464_LockTip = {
    Text = "Completa l'Immersione Psichica \"Banchetto di Fiamme\" in difficoltà Difficile"
  },
  CollectionHall_100464_Title = {
    Text = "Maschera della Pestilenza"
  },
  CollectionHall_100465_Desc = {
    Text = "Wanda vedeva il suo passato glorioso riflesso nel lago.\nI suoi ricordi si stavano dissolvendo in sogni illusori: visioni di sé stessa assisa tra rovine infinite, mentre osservava tutto ciò che le apparteneva dissolversi come fantasmi.\nE quando anche quel sogno era sul punto di svanire, l'emissario dal flauto emergeva dalla nebbia, guidandola verso il sentiero del Defunto."
  },
  CollectionHall_100465_LockTip = {
    Text = "Completa l'Immersione Psichica \"Banchetto di Fiamme\""
  },
  CollectionHall_100465_Title = {
    Text = "Riflesso nel Lago"
  },
  CollectionHall_100466_Desc = {
    Text = "Dalle stelle eterne, la Presenza che arde in eterno apre i Suoi occhi ancora una volta, riversando potere immortale su questo mondo torbido, corrotto, eppure splendidamente azzurro: un Pianeta radiosamente blu come quando il sole divoratore di cieli discese su di esso per la prima volta, quattro miliardi di anni fa."
  },
  CollectionHall_100466_LockTip = {
    Text = "Completa l'Immersione Psichica \"Giorno eterno immortale\""
  },
  CollectionHall_100466_Title = {
    Text = "Riunione di Quattro Miliardi di Anni"
  },
