  CollectionHall_118636_Title = {
    Text = "<OrangeQuality:Invito del mutaforma>"
  },
  CollectionHall_120344_Title = {
    Text = "Ci rivedremo"
  },
  CollectionHall_120463_LockTip = {
    Text = "Sbloccato in: Capitolo 4-15"
  },
  CollectionHall_120463_Title = {
    Text = "Innocenza Registrata"
  },
  CollectionHall_120464_LockTip = {
    Text = "Restate sintonizzati"
  },
  CollectionHall_120464_Title = {
    Text = "Borsa Golosa"
  },
  CollectionHall_120465_LockTip = {
    Text = "Sbloccato in: Capitolo 4-5"
  },
  CollectionHall_120465_Title = {
    Text = "Scricchiolio"
  },
  CollectionHall_120466_LockTip = {
    Text = "Sbloccato in: Capitolo 3-10"
  },
  CollectionHall_120466_Title = {
    Text = "Telegramma Silenzioso"
  },
  CollectionHall_121154_Title = {Text = "Paradiso"},
  CollectionHall_121341_Desc = {
    Text = "La \"Principessa\" ha abbracciato pienamente il suo ruolo: ora è la \"Madre Divina,\" incaricata di nutrire il \"Feto Divino\"—l'essere cruciale all'interno dell'Ordine dei Navigatori. \nUn tempo era una ragazza che cercava disperatamente la libertà, intraprendendo lo stesso viaggio di fuga a bordo della Sona-nyl documentato da Murphy di Mythag. \nEppure, in un mondo privo di benevoli custodi, il destino spezzò brutalmente il nobile collo del giovane cigno. \nLa sua stirpe contorta la avviluppò senza tregua; nemmeno la morte del suo corpo poté offrirle scampo. Si costringe a ripetere, ancora e ancora, \"Io sono la nobile Madre Divina,\" usando la frase come un mero atto di autosuggestione e persuasione. \nResta solo l'obbedienza, solo la compulsione a obbedire. Sottomettersi al falso oracolo, cedere all'assurdo destino. Solo allora, dall'infinita amarezza della sua esistenza, può assaporare con riluttanza un accenno di dolce, fugace fantasia."
  },
  CollectionHall_121341_LockTip = {
    Text = "Risveglia \"Murphy: Falsonata\""
  },
  CollectionHall_121341_Title = {
    Text = "Murphy: Falsonata"
  },
  CollectionHall_121381_Desc = {
    Text = [[
Hai scambiato 1000 ghiande per una storia da un altro mondo.
Una storia di eroi e del dio demone, di veglia e perseveranza.
Una storia di impotenza e riluttanza, di vecchi amici e nuovi.
Una storia che fu.]]
  },
  CollectionHall_121381_LockTip = {
    Text = "Completa il Collegamento Multiversale \"Il Mio Turno\""
  },
  CollectionHall_121381_Title = {
    Text = "L'Eco della Taverna Cosmica"
  },
  CollectionHall_121382_Desc = {
    Text = [[
Molto, molto tempo dopo, finalmente si canta una ballata degli Uccelli Gemelli.
Parla della redenzione attraverso la resurrezione, delle anime gemelle che furono legate insieme.]]
  },
  CollectionHall_121382_LockTip = {
    Text = "Completa il Paesaggio Onirico \"Oltre i cieli: Parte II\""
  },
  CollectionHall_121382_Title = {
    Text = "Ballata degli Uccelli Senz'Ali"
  },
  CollectionHall_121383_Desc = {
    Text = "Il giovane pagò il prezzo richiesto per tutto ciò che era effimero.\nOra, solo lo scettro silente gli fa compagnia.\nIl giovane re si addormenterà, e nei suoi sogni incontrerà la fine del mondo."
  },
  CollectionHall_121383_LockTip = {
    Text = "Completa l'Immersione Psichica \"Giorno dell'Incoronazione\""
  },
  CollectionHall_121383_Title = {
    Text = "Terra Sconfinata di Dolore e Solitudine"
  },
  CollectionHall_121384_Desc = {
    Text = [[
Ti circondano, ti venerano, ti accompagnano.
Spiegano le vele verso il Creatore.]]
  },
  CollectionHall_121384_LockTip = {
    Text = "Completa Livello 9-11"
  },
  CollectionHall_121384_Title = {
    Text = "Spiega le Vele verso il Dio Creatore"
  },
  CollectionHall_121385_Desc = {
    Text = "Quelle sono ali rinascite dalla distruzione, ottenute attraverso il sacrificio in cambio della libertà.\nLa profezia del destino si è compiuta. Nel rimorso amaro, egli giura che i debiti di sangue saranno ripagati col sangue."
  },
  CollectionHall_121385_LockTip = {
    Text = "Completa il Paesaggio Onirico \"Oltre i cieli: Parte II\""
  },
  CollectionHall_121385_Title = {
    Text = "Quando Sorge la Tempesta"
  },
  CollectionHall_121386_Desc = {
    Text = "Sin dal principio dell'assurdo e caotico sogno, Loro erano destinati ad affrontare il proprio fato.\nEppure hanno vissuto troppo, e definito troppo.\nHanno deciso, con il massimo grado di sanità mentale che un essere umano possa conservare, di volgere lo sguardo alla propria origine: La Volontà Suprema."
  },
  CollectionHall_121386_LockTip = {
    Text = "Completa Livello 9-11"
  },
  CollectionHall_121386_Title = {
    Text = "Guerra del Destino Primordiale"
  },
  CollectionHall_121387_Desc = {
    Text = "Ottenere, perdere, recidere, Sacrificare.\nL'eroe ha pagato fino all'ultimo il prezzo, e l'Autorità di custodire il Tesoro segreto è la Loro ricompensa."
  },
  CollectionHall_121387_LockTip = {
    Text = "Completa Livello 9-13"
  },
  CollectionHall_121387_Title = {
    Text = "Occhio Senza Pupilla"
  },
  CollectionHall_121388_Desc = {
    Text = "Si cinse da solo la corona; si incatenò da solo al trono.\nQuello fu un calore breve e illusorio; quella fu la gloria passata destinata a dissolversi."
  },
  CollectionHall_121388_LockTip = {
    Text = "Completa l'Immersione Psichica \"Giorno dell'Incoronazione\""
  },
  CollectionHall_121388_Title = {
    Text = "Il Viaggio Solitario del Giovane Re"
  },
  CollectionHall_121389_Desc = {
    Text = "Nonostante la situazione sfavorevole, un lieve sorriso si incurva all'angolo delle tue labbra.\n\"È il mio turno di pescare!\"\nChe sia alla Taverna Cosmica o a Mythag, sottovalutare la capacità offensiva di un supporto ti costerà cara, Ignatiss!"
  },
  CollectionHall_121389_LockTip = {
    Text = "Completa il Collegamento Multiversale \"Il Mio Turno\""
  },
  CollectionHall_121389_Title = {
    Text = "È Il Mio Turno!"
  },
  CollectionHall_121390_Desc = {
    Text = "Nessuna leggenda completa è priva di nemici divenuti alleati."
  },
  CollectionHall_121390_LockTip = {
    Text = "Completa Livello Difficile 9-10"
  },
  CollectionHall_121390_Title = {
    Text = "Nemici, Amici"
  },
  CollectionHall_121391_Desc = {
    Text = "D'ora in avanti, ti ergi come Custode tra i molti studenti e studiosi di Mythag."
  },
  CollectionHall_121391_LockTip = {
    Text = "Completa Livello Difficile 9-11"
  },
  CollectionHall_121392_Desc = {
    Text = "Possiamo essere istanti fugaci nell'eternità, granelli di sabbia in un torrente furioso.\nEppure la nostra preziosa eternità risiede in questo mondo ordinario, poiché non importa quanto folle e caotico divenga il mondo—\nla dignità umana sarà edificata sullo splendore della ragione."
  },
  CollectionHall_121392_LockTip = {
    Text = "Completa Livello 9-11"
  },
  CollectionHall_121392_Title = {
    Text = "Inno Eterno"
  },
  CollectionHall_121393_Desc = {
    Text = "Gli avventurieri si tuffarono a capofitto nelle fiabe; ogni fiaba era uguale, con bestie, diavoli, fate e l'ignoto oltre.\nMa alla fine della fiaba, oltre la libertà fugace e i desideri sfuggenti, giace un cuore finto che egli è condannato a portare."
  },
  CollectionHall_121393_LockTip = {
    Text = "Completa il Paesaggio Onirico \"Oltre i cieli: Parte II\""
  },
  CollectionHall_121393_Title = {
    Text = "Verso le Stelle"
  },
  CollectionHall_121394_Desc = {
    Text = "Questa è la Taverna Cosmica, situata nella frattura spaziale di un altro universo.\nIl portale che connette universi diversi brilla della vasta luce stellare, dando il benvenuto al tuo arrivo.\nUn momento... Dove diavolo siamo?"
  },
  CollectionHall_121394_LockTip = {
    Text = "Completa il Collegamento Multiversale \"Il Mio Turno\""
  },
  CollectionHall_121394_Title = {
    Text = "Benvenuti alla Taverna Cosmica"
  },
  CollectionHall_121395_Desc = {
    Text = "La Lama di Mythag ti assicurerà la vittoria in questo duello.\nIl legame tra te e il tuo compagno è infrangibile.\nQuesto non cambierà mai, anche se un giorno vi ritroverete in universi diversi."
  },
  CollectionHall_121395_LockTip = {
    Text = "Completa il Collegamento Multiversale \"Il Mio Turno\""
  },
  CollectionHall_121395_Title = {
    Text = "Lama di Mythag!"
  },
  CollectionHall_121396_Desc = {
    Text = "\"Non hai completato la tua Missione Quotidiana? Che ne dici di una partita a Carte Cosmiche?\"\n\"Non hai superato la Zona D-Effetto? Che ne dici di una partita a Carte Cosmiche?\"\n\"Questo è Traphase, non Carte Cosmiche! Raccoglierò 1000 ghiande, stai a guardare!\""
  },
  CollectionHall_121396_LockTip = {
    Text = "Completa il Collegamento Multiversale \"Il Mio Turno\""
  },
  CollectionHall_121396_Title = {
    Text = "Giochiamo a Carta Cosmica!"
  },
  CollectionHall_121397_Desc = {
    Text = "Chiama il mio nome, ti prego, prima dell'alba che mi condanna all'oblio."
  },
  CollectionHall_121397_LockTip = {
    Text = "Completa Livello Difficile 9-11"
  },
  CollectionHall_121397_Title = {
    Text = "Ex Oblivione @2"
  },
  CollectionHall_121398_Desc = {
    Text = [[
"Vieni a firmare un contratto con me e diventa un Maestro delle Carte!"
Questa fanciulla drago di un altro mondo ti rivolge un invito entusiasta quanto sconcertante.
Per risolvere rapidamente questa anomalia dello Spazio Fasico, non hai altra scelta che acconsentire.]]
  },
  CollectionHall_121398_LockTip = {
    Text = "Completa il Collegamento Multiversale \"Il Mio Turno\""
  },
  CollectionHall_121398_Title = {
    Text = "Ignatiss, il Taverniere!"
  },
  CollectionHall_121399_Desc = {
    Text = "I futuri viandanti, sotto il peso del gravoso dono, troveranno questa nota a piè di pagina:\nColui che fuggì la corona dell'eroe divenne l'eroe; colui che ebbe cari i suoi amici li perse tutti, tranne uno."
  },
  CollectionHall_121399_LockTip = {
    Text = "Completa l'Immersione Psichica \"Giorno dell'Incoronazione\""
  },
  CollectionHall_121399_Title = {
    Text = "Camminerò da Solo"
  },
  CollectionHall_121400_Desc = {
    Text = "Liberarsi dal Signore, ergersi dinanzi al Signore, sfidare il Signore.\nLa tua storia non è nota a nessuno, eppure il tuo ricordo dovrà Sopportare per sempre insieme al mondo."
  },
  CollectionHall_121400_LockTip = {
    Text = "Completa Livello 9-13"
  },
  CollectionHall_121400_Title = {
    Text = "Il Dio Cieco e Idiota"
  },
  CollectionHall_121401_Desc = {
    Text = "Tutto cessa di avere significato, e così ti trovi qui.\nTutto ciò che è accaduto in passato costituisce l'intero significato — come definito da te stesso — perché tu possa trovarti qui."
  },
  CollectionHall_121401_LockTip = {
    Text = "Completa Livello 9-13"
  },
  CollectionHall_121401_Title = {
    Text = "Esistenzialismo"
  },
  CollectionHall_121402_Desc = {
    Text = "È Il Sentiero verso di Loro; è Il Sentiero lontano da Loro.\nTutto sta per separarsi, per finire, per ricominciare.\nLa figura dinanzi al Cancello ha da allora iniziato una lunga Attesa, in Attesa della Chiave d'argento che guidi il tuo cammino verso casa."
  },
  CollectionHall_121402_LockTip = {
    Text = "Completa Livello 9-13"
  },
  CollectionHall_121402_Title = {
    Text = "Il Sentiero verso di Loro"
  },
  CollectionHall_121403_Desc = {
    Text = "I fili di possibilità di Loro si divisero, conversero e si dispersero.\nFinché l'unico e solo salvatore giunse, finché Loro infine varcarono la soglia dell'unica e sola Fine Ultima."
  },
  CollectionHall_121403_LockTip = {
    Text = "Completa Livello Difficile 9-10"
  },
  CollectionHall_121403_Title = {
    Text = "L'Unica Vera Fine"
  },
  CollectionHall_121404_Desc = {
    Text = "Il giovane re accettò il patto.\n\"Il mio regno sarà salvo e intatto,\" disse."
  },
  CollectionHall_121404_LockTip = {
    Text = "Completa l'Immersione Psichica \"Giorno dell'Incoronazione\""
  },
  CollectionHall_121404_Title = {
    Text = "Coronazione"
  },
  CollectionHall_121405_Desc = {
    Text = "In questa frattura spaziale in frantumi sorgeva un tempo la leggendaria Taverna Cosmica.\nI portali che collegavano universi diversi un tempo brillavano della vasta luce stellare, accogliendo l'arrivo di ogni Maestro di Carte.\nE tu sei la prova che tutto questo è esistito."
  },
  CollectionHall_121405_LockTip = {
    Text = "Completa il Collegamento Multiversale \"Il Mio Turno\""
  },
  CollectionHall_121405_Title = {
    Text = "Addio, Maestro delle Carte!"
  },
  CollectionHall_121406_Desc = {
    Text = "Il Creatore ha posato su di te Il Suo Sguardo, e tu hai perforato il Suo occhio."
  },
  CollectionHall_121406_LockTip = {
    Text = "Completa Livello 9-13"
  },
  CollectionHall_121406_Title = {
    Text = "Lo Sguardo della Fine"
  },
  CollectionHall_121407_Desc = {
    Text = [[
Guerriero. Vendicatore. Schiavo. Padrone. Mercante.
Stessa posizione? Posizioni diverse? La stessa posizione.]]
  },
  CollectionHall_121407_LockTip = {
    Text = "Completa Livello 9-11"
  },
  CollectionHall_121407_Title = {
    Text = "Canto di Battaglia del Multiverso"
  },
  CollectionHall_121408_Desc = {
    Text = "Sai che non stai combattendo per qualcosa di grandioso.\nÈ per marinare la scuola, per i compiti, per i dolci, per gli amici, per il calore del focolare, per oziare nelle ore vuote.\nSei soltanto una persona ordinaria, una che muore per un giorno ordinario."
  },
  CollectionHall_121408_LockTip = {
    Text = "Completa Livello Difficile 9-11"
  },
  CollectionHall_121408_Title = {
    Text = "Martire per un Giorno Ordinario"
  },
  CollectionHall_121409_Desc = {
    Text = "Gli animali, tutti gli animali superiori, sono inevitabilmente governati dai comportamenti sociali.\nEppure lei cammina verso la morte di propria volontà e, come desiderato, decostruisce la verità.\nUna geniale folle senza pari, preferisce portare la distruzione con le proprie mani, concedendo agli esseri senzienti la liberazione dal consumare l'arsenico chiamato Speranza."
  },
  CollectionHall_121409_LockTip = {
    Text = "Completa Livello 9-13"
  },
  CollectionHall_121409_Title = {
    Text = "Decostruzione del Comportamento Comunitario"
  },
  CollectionHall_121410_Desc = {
    Text = "Un flusso incessante di acqua amara fu inviato da Lui dagli alti cieli, raccogliendosi, confluendo;\nfinché non formò il fiume che siamo destinati ad attraversare prima che la nostra carne e il nostro sangue si intreccino."
  },
  CollectionHall_121410_LockTip = {
    Text = "Completa il Paesaggio Onirico \"Oltre i cieli: Parte II\""
  },
  CollectionHall_121410_Title = {
    Text = "Fiume Amaro"
  },
  CollectionHall_121411_Desc = {
    Text = "Si congedarono con l'aspettativa di un ricongiungimento.\nPoiché questa è l'Amata, poiché la morte dell'Amata non è segnata dal fato."
  },
  CollectionHall_121411_LockTip = {
    Text = "Completa Livello 9-11"
  },
  CollectionHall_121411_Title = {
    Text = "La Morte di una Persona Amata"
  },
  CollectionHall_121412_Desc = {
    Text = "Fermati, riprendi fiato.\nAnche se l'argomento in questione è l'apocalisse, non Tutti hanno l'occasione di affrontare tre mentori così monumentali contemporaneamente."
  },
  CollectionHall_121412_LockTip = {
    Text = "Completa Livello 9-13"
  },
  CollectionHall_121412_Title = {Text = "Intermezzo"},
  CollectionHall_121413_Desc = {
    Text = [[
La storia delle mille ghiande deve sempre iniziare dalla prima.
In Traphase, ogni volta che giochi una carta, un bagliore di memoria dorata guizza negli occhi di Ignatiss.]]
  },
  CollectionHall_121413_LockTip = {
    Text = "Completa il Collegamento Multiversale \"Il Mio Turno\""
  },
  CollectionHall_121413_Title = {
    Text = "Ricariche illimitate!"
  },
  CollectionHall_121414_Desc = {
    Text = "La Follia, preludio alla distruzione, è la logica soggiacente del mondo ordinato.\nPerirà Esso? Il mondo sarà distrutto?\nNessuno lo sa.\nMa dinanzi al Creatore, la follia sta alimentando la rinascita di Loro e del mondo."
  },
  CollectionHall_121414_LockTip = {
    Text = "Completa Livello 9-11"
  },
  CollectionHall_121414_Title = {
    Text = "Fuga della Follia"
  },
  CollectionHall_121415_Desc = {
    Text = "Qual è la cosa più irrazionale al mondo?\nEsso. Non ha scopo, non nutre rancori, non distingue il bene dal male.\nDesidera soltanto, al risveglio, ridurre in polvere e cenere tutto ciò che è sorto nel sogno."
  },
  CollectionHall_121415_LockTip = {
    Text = "Completa Livello 9-13"
  },
  CollectionHall_121415_Title = {Text = "Percossa"},
  CollectionHall_121416_Desc = {
    Text = "In quanto Frammento unico, diventare un dio è semplice.\nAllora, qual è il prezzo?"
  },
  CollectionHall_121416_LockTip = {
    Text = "Completa Livello 9-13"
  },
  CollectionHall_121416_Title = {
    Text = "Ascensione alla Divinità"
  },
  CollectionHall_121417_Desc = {
    Text = "Nel lungo arco della civiltà umana, abbiamo costruito innumerevoli cose.\nVi sono materia, Spirito; vi sono sopravvivenza, amore, conflitto e guerra.\nEppure, tutto ciò non è che l'insignificante rumore nel sogno del Creatore, e una raccolta fittizia che abbiamo trascurato di decifrare."
  },
  CollectionHall_121417_LockTip = {
    Text = "Completa Livello 9-13"
  },
  CollectionHall_121417_Title = {
    Text = "Collezione Fittizia"
  },
  CollectionHall_121418_Desc = {
    Text = "Il più codardo Custode nella storia di Mythag morì in una beatitudine assoluta."
  },
  CollectionHall_121418_LockTip = {
    Text = "Completa Livello Difficile 9-11"
  },
  CollectionHall_121418_Title = {
    Text = "L'Eroe Decise di Fuggire"
  },
  CollectionHall_121898_LockTip = {
    Text = "Completa Capitolo Astrale 4-0"
  },
  CollectionHall_121898_Title = {
    Text = "Pellegrinaggio Illusorio Eterno"
  },
  CollectionHall_121901_LockTip = {
    Text = "Completamento Capitolo Astrale 4-16"
  },
  CollectionHall_121901_Title = {
    Text = "Sette Giorni"
  },
  CollectionHall_122565_LockTip = {
    Text = "Completa un qualsiasi Livello dell'Evento a tempo limitato \"Sacramento Avvolto dalla Nebbia: L'Io Perduto\""
  },
  CollectionHall_122565_Title = {
    Text = "Sacramento Avvolto nella Nebbia: L'Io Perduto"
  },
  CollectionHall_123756_Title = {
    Text = "Battesimo d'Argento e Sangue"
  },
  CollectionHall_124124_Desc = {
    Text = "Esistono possibilità di un secondo incontro, persino con un Infante che non dovrebbe esistere, o un dio nato da un errore."
  },
  CollectionHall_124124_LockTip = {
    Text = "Si sblocca dopo aver completato Capitolo Astrale 4-16"
  },
  CollectionHall_124124_Title = {
    Text = "Secondo Incontro"
  },
  CollectionHall_124125_Desc = {
    Text = "Oh... quindi esiste un finale ancora peggiore."
  },
  CollectionHall_124125_LockTip = {
    Text = "Si sblocca dopo aver completato Capitolo Astrale 4-16"
  },
  CollectionHall_124125_Title = {
    Text = "La Morte di Lei, di Lui e di Esso"
  },
  CollectionHall_124126_Desc = {
    Text = "Come descriveresti un compagno che se n'è andato all'apice del suo splendore?\nNon parlare della sua brillantezza. Descrivi il freddo metallo del suo braccio; descrivi la fragranza di cedro che indugiava nella sua scia."
  },
  CollectionHall_124126_LockTip = {
    Text = "Si sblocca dopo aver completato Capitolo Astrale 4-16"
  },
  CollectionHall_124126_Title = {Text = "Cedro"},
  CollectionHall_124127_Desc = {
    Text = [[
Qualcuno ti attende alla fine del tuo viaggio. Lo sai a memoria.
Ma non sei ancora fuggito. Ancora una volta precipiti dall'alto.]]
  },
  CollectionHall_124127_LockTip = {
    Text = "Si sblocca dopo aver completato Capitolo Astrale 4-10: Difficile"
  },
  CollectionHall_124127_Title = {Text = "La Caduta"},
  CollectionHall_124128_Desc = {
    Text = [[
Il bambino non appartiene alla madre. "Lui" ha preso la Sua decisione: tutti devono restare qui.
Restare nel Suo dolce paradise, che perdura in eterno.]]
  },
  CollectionHall_124128_LockTip = {
    Text = "Si sblocca dopo aver completato Capitolo Astrale 4-10: Difficile"
  },
  CollectionHall_124128_Title = {
    Text = "Dolce Paradise"
  },
  CollectionHall_124129_Desc = {
    Text = "Sei arrivato troppo tardi. Questa versione di lei non è riuscita a fuggire.\nÈ stata spartita e divorata; è rimasta sola e inerme, legata a un falso cordone ombelicale."
  },
  CollectionHall_124129_LockTip = {
    Text = "Si sblocca dopo aver completato Capitolo Astrale 4-16"
  },
  CollectionHall_124129_Title = {
    Text = "Falso Cordone Ombelicale"
  },
  CollectionHall_124130_Desc = {
    Text = "3,14159@2, 3,141592@3, 3,14159265@4...\nÈ un cerchio infinito nella neve, un Pi greco crudele, senza fine."
  },
  CollectionHall_124130_LockTip = {
    Text = "Si sblocca dopo aver completato Capitolo Astrale 4-10: Difficile"
  },
  CollectionHall_124130_Title = {
    Text = "\"3,14159@4\""
  },
  CollectionHall_124131_Desc = {
    Text = "Ancora una volta, sei arrivato troppo tardi. Non indugiare. Più in fretta, ancora più in fretta.\nCorri verso il prossimo finale."
  },
  CollectionHall_124131_LockTip = {
    Text = "Si sblocca dopo aver completato Capitolo Astrale 4-16"
  },
  CollectionHall_124131_Title = {
    Text = "Un Finale Possibile"
  },
  CollectionHall_124132_Desc = {
