  CollectionHall_124141_Desc = {
    Text = "Lei e Lei hanno ciascuna le proprie devozioni; Lui e Lui custodiscono ciascuno la propria ribellione e lealtà.\nLei tessé una menzogna colossale; Lui e Lui e Lei e Lei scelsero tutti di recitare la propria parte.\nFocolare. Tutti insieme formarono un dolce, inseparabile focolare."
