  CollectionHall_133770_Desc = {
    Text = "Benvenuti, passeggeri!\nLa Festa di primavera si avvicina! In questa gioiosa stagione di riunioni e nuovi inizi, tutto il nostro equipaggio porge i più sentiti auguri a voi viaggiatori stanchi che affrontate il lungo viaggio verso casa:\n\nAuguri per una felice Festa di primavera, gioiosi ritrovi familiari, un viaggio veloce e il meglio assoluto! <(￣︶￣)↗[GO!]"
  },
  CollectionHall_133770_LockTip = {
