  CollectionHall_133770_Title = {
    Text = "Frenetico · Ferrovia Celeste"
  },
  CollectionHall_133771_Desc = {
    Text = "Attenzione passeggeri, ci scusiamo per il disagio: a causa dell'umore del conduttore, questo espresso effettuerà una sosta non programmata. Annunceremo l'orario esatto di partenza tramite l'altoparlante al termine del massacro reciproco.\nDurante questa sosta, l'aria condizionata, l'illuminazione e i servizi igienici rimarranno pienamente operativi. Vi invitiamo a utilizzarli a vostra discrezione in base alle vostre esigenze di massacro, per evitare di non trovarvi in pericolo.\nDopotutto, il solo dovere dell'espresso della gioia è portare allegria a tutti i nostri passeggeri! ~(￣▽￣~)(~￣▽￣)~"
  },
  CollectionHall_133771_LockTip = {
