  },
  CollectionHall_142157_Desc = {
    Text = "I ricordi Battono di Ciglia e si sovrappongono, il finale è di dubbia autenticità.\nMa questo è davvero importante?\nDopotutto, non tutte le storie iniziano necessariamente con l'amore, ma tutte avranno la morte come punto finale."
  },
  CollectionHall_142157_LockTip = {
