  CollectionHall_142157_Title = {
    Text = "Quattro Ricordi"
  },
  CollectionHall_142158_Desc = {
    Text = "Se un giorno anche tu, come me, ti ritrovassi in uno scenario di Caro dilaniata, putrefatta e in decomposizione.\nAllora sicuramente potresti capire—\nIl momento in cui le sue piccole dita sfiorano le mie è un miracolo raro in questo mondo."
  },
