  },
  CollectionHall_142158_Title = {Text = "Miracolo"},
  CollectionHall_142159_Desc = {
    Text = [[
Sei stanco anche tu della vita ordinaria, ciclica, monotona, giorno dopo giorno?
Proviamo qualcosa di nuovo: un altro orizzonte sta spalancando le sue fauci insanguinate, rivolgendoti un caloroso invito.]]
  },
  CollectionHall_142159_LockTip = {
    Text = "Azzera Collegamento Multiverso \"Semi d'amore dimenticati\""
  },
  CollectionHall_142159_Title = {
    Text = "Dominio di Sangue"
  },
  CollectionHall_142160_Desc = {
    Text = "L'amore è sublime, l'amore è Avidità; l'amore è Benedire, l'amore è Maledizione.\nL'amore nasce con l'acqua, e con l'acqua svanirà.\nMa la stagione delle piogge non tornerà più."
  },
  CollectionHall_142160_LockTip = {
