  },
  CollectionHall_142160_Title = {
    Text = "Stagione delle Piogge"
  },
  CollectionHall_142161_Desc = {
    Text = "Ogni Vita nasce nell'ignoranza, trae nutrimento da tutte le cose, trasforma l'ambiente, saccheggia le risorse, si offre devozione.\nQuesto è il peccato originale da cui non si può fuggire."
  },
  CollectionHall_142161_LockTip = {
    Text = "Azzera Collegamento Multiverso \"Semi d'amore dimenticati\""
  },
  CollectionHall_142161_Title = {
    Text = "Peccato Originale"
  },
  CollectionHall_142162_Desc = {
    Text = "Esiste una Pianta chiamata tarassaco, che lascia volare i suoi semi nel Vento.\nI soffici semi vagano con il Vento, allontanandosi sempre di più dalla loro terra natia.\nSolo e solitario, quando deciderà la propria destinazione?\nQuando, nel deserto, ci sarà un'unica persona ad amare quel tarassaco."
  },
  CollectionHall_142162_LockTip = {
    Text = "Azzera Collegamento Multiverso \"Semi d'amore dimenticati\""
  },
  CollectionHall_142162_Title = {
    Text = "Dove Va il Tarassaco"
  },
  CollectionHall_142163_Desc = {
    Text = "Vasto cielo e terra, immenso mare di sabbia.\nUn luogo deserto dove ci siamo solo tu e io.\nUn eterno vagabondaggio d'amore in libertà."
  },
  CollectionHall_142163_LockTip = {
