  CollectionHall_142163_Title = {
    Text = "Vagabondaggio nel Mare di Sabbia"
  },
  CollectionHall_142164_Desc = {
    Text = "Posso chiamare il tuo nome? Anche se il mondo svanisce.\"\nSe tutti i ricordi saranno annientati e dispersi, il nero Oblio Divorerà ogni passato che non ha fatto in tempo a essere rimpianto.\nAllora stringiamoci la mano, lasciando che la luce argentea ci colleghi.\nIn un nuovo Sogno, nella primavera in cui i teneri semi germogliano."
  },
  CollectionHall_142164_LockTip = {
    Text = "Azzera Collegamento Multiverso \"Semi d'amore dimenticati\""
  },
  CollectionHall_142164_Title = {
    Text = "Song of Memento"
  },
  CollectionHall_142165_Desc = {
    Text = "Canta, la Vita splendente loda la libertà, seminando il Gynoecium della speranza in ogni luogo raggiunto."
  },
  CollectionHall_142165_LockTip = {
    Text = "Azzera Collegamento Multiverso \"Semi d'amore dimenticati\" a difficoltà Difficile"
  },
  CollectionHall_142165_Title = {
    Text = "Inno d'Apertura"
  },
  CollectionHall_142868_Desc = {
    Text = "<Title:Introduzione>\nPontos ricorda sempre come si sentì il giorno in cui scoprì la storia della sua famiglia. Prima di allora, non era mai stato pronto ad assumersi alcuna responsabilità: tutti lo amavano, era affascinante, divertente, spensierato.\n@1Le navi che transitavano tutto l'anno nel porto reale lo esentavano dal dover affrontare la monotonia quotidiana. Aveva ascoltato troppe storie, molti dicevano che fosse un uomo di mondo, tanto che non riusciva ad ammettere di poter essere come tutti gli altri.\nCosì fu travolto da una gioia immensa, inaspettata eppure del tutto naturale. Per di più, l'entità ben più misteriosa e grandiosa che si celava dietro il demone che aveva guidato la sua famiglia di generazione in generazione lo aveva riconosciuto — era nato diverso dagli altri.\nEppure uno scherzo di \"N\" spinse i fanatici a distruggere un intero villaggio in un attacco indiscriminato lungo la costa.\nIncapace di affrontare quella catastrofe improvvisa, per ottenere il potere degli abissi, Pontos scelse di sacrificare il proprio corpo a @3, sacrificando con esso tutte le sue possibilità.\nMa che importava? Nulla avrebbe mai potuto sfuggire al suo controllo.\nNon avrebbe mai più perso nulla."
  },
  CollectionHall_142868_LockTip = {
    Text = "Si sblocca dopo aver risvegliato \"Pontos\""
  },
  CollectionHall_142868_Title = {Text = "Pontos"},
