  CollectionHall_143473_Desc = {
    Text = "Scricchiola, scricchiola.\nO Destino, la tua ruota gira senza sosta.\nPovertà e potere vengono da te dissolti come ghiaccio.\nTi veli e nascondi il tuo volto,\neppure risplendi anche su di me......"
