  CollectionHall_143480_Desc = {
    Text = "Un po' di bitter, 20ml di vermut dolce, un po' di sherry, riempire di ghiaccio e mescolare — è un ottimo aperitivo, e anche uno spettacolo andato in scena cinquecento volte."
