  CollectionHall_143480_Title = {Text = "Adonis"},
  CollectionHall_143481_Desc = {
    Text = "Se tratti il Destino come un pagliaccio, il Destino non ti renderà suo schiavo.\nAccoglilo con una risata che non si ferma mai, e invochiamo insieme il Suo nome —\nGioia."
  },
