  CollectionHall_143481_Title = {
    Text = "L'arrivo del buffone"
  },
  CollectionHall_143482_Desc = {
    Text = "\"Ti odio, odio il tuo Bozzolo che ti sei costruito, odio la tua Senza Speranza, odio che tu abbia abbandonato te stessa.\"\n\"......Eppure questo odio brucia anche me, perché, ti amo anch'io.\""
