    Text = "Elegia del Fantasma Vendicatore"
  },
  CollectionHall_143483_Desc = {
    Text = "Il mondo ti offre innumerevoli bivi tra cui scegliere, ma tutti confluono nello stesso punto — chiamato Distruzione, chiamato fine."
  },
  CollectionHall_143483_LockTip = {
