  CollectionHall_143483_Title = {
    Text = "Copia del Mondo"
  },
  CollectionHall_143484_Desc = {
    Text = "Il sipario si alza e cade, gli spettacoli si avvicendano, eppure lei è ancora nel teatro — è drammaturga, Il Pubblico e attrice al tempo stesso.\nO padrona del Destino, sei così crudele, eternamente silenziosa, eppure perché versi lacrime?"
  },
  CollectionHall_143484_LockTip = {
    Text = "Completa l'Operazione Regno Astrale 5-16 per sbloccare"
