  CollectionHall_143484_Title = {
    Text = "Il Gioco del Destino Intrecciato"
  },
  CollectionHall_143485_Desc = {
    Text = "Se la Distruzione è inevitabile, strappare la rete del Destino porterà forse la vera Redenzione?\nNessuno può rispondere, nessun dio può rispondere.\nMa almeno, anche le sofferenze infinite periranno insieme."
