  CollectionHall_143488_Desc = {
    Text = "Gli archi si alzano lentamente, l'Ancella intona il suo canto.\nColei che stava dietro le quinte si avanza sul palco, ti fa un inchino e ti invita come Testimone Silenzioso di questo percorso già stabilito."
