  CollectionHall_143490_Desc = {
    Text = "Il sipario si apre e i bizzarri personaggi entrano in scena uno dopo l'altro.\nCantano, Danzano, e prima che il Destino precipiti, portano ostinatamente lo spettacolo sul palco, anche se il finale è già scritto."
