  CollectionHall_144450_Title = {
    Text = "Il Sole che Sprofonda"
  },
  CollectionHall_144451_Desc = {
    Text = "La luna ridacchia, la luna sussurra.\nFato, oh fato, dice la luna — il fato sta per cadere."
