    Text = "La Luna Cadente"
  },
  CollectionHall_144452_Desc = {
    Text = "Inconsapevolmente, aveva fatto sì che le persone lasciassero qualcosa con lui.\nInconsapevolmente, aveva lasciato qualcosa dietro di sé, proprio come avevano fatto loro."
