    Text = "Completa il Prologo"
  },
  CollectionHall_48616_Title = {
    Text = "Università di Mythag"
  },
  CollectionHall_48618_Title = {Text = "Prologo"},
  CollectionHall_48619_Desc = {
    Text = "<Title:Data di Fondazione>\nD.D. 186\n\n<Title:Fondatore>\nPaesi Firmatari del \"Trattato di Mystia\"\n\n<Title:Panoramica>\nUn'Organizzazione Globale composta da esseri umani ordinari.\nIstituita con finanziamenti di vari Governi Nazionali, opera in modo indipendente e funge da gestore ufficiale e primo soccorritore per i Fenomeni-D.\nLa maggior parte dei membri sono individui ordinari privi di formazione nel Misticismo o di abilità soprannaturali, con l'obiettivo primario e unico di combattere la Dissoluzione.\nNumerosi uffici sono stati istituiti in vari paesi, ciascuno responsabile di differenti regioni.\n\"Solenne e rigida\" è la prima impressione che Tutti hanno dell'Organizzazione, con le loro uniformi bianche eccessivamente candide che appaiono rigide quanto la loro postura."
  },
