  CollectionHall_49000_Title = {Text = "Favore"},
  CollectionHall_49001_Desc = {
    Text = "Dopo innumerevoli anni trascorsi ad accumulare un potere immenso, con la presente dichiariamo—"
  },
  CollectionHall_49001_Title = {Text = "Emersione"},
  CollectionHall_49002_Desc = {
    Text = "Invoca il suo nome: Erexis."
