  CollectionHall_49003_Title = {Text = "Sussurro"},
  CollectionHall_49004_Desc = {
    Text = "Benedizioni per gli uccelli e le api."
  },
  CollectionHall_49004_Title = {Text = "Speranza"},
  CollectionHall_49015_Desc = {
    Text = "Dopo che il Cataclisma svanì senza lasciare traccia e la crisi fu temporaneamente risolta, la Squadra Operazioni Speciali di Mythag partì da Yakutsk con un \"Guadagno Inaspettato.\"\n\nLa signorina Dexter si voltò a guardare l'enorme cratere nel sito dell'esplosione, notando che germogli di piante sconosciute avevano silenziosamente fatto breccia nel terreno senza che lei se ne accorgesse.\n\nTirò un sospiro di sollievo, sentendosi il cuore leggero.\n\nQuesta foresta accoglierà sicuramente la sua primavera di nuovo l'anno prossimo.\n\nI salici germoglieranno alla prossima primavera, e i mughetti fioriranno in silenzio dopo la prossima stagione delle piogge, con ogni forma di vita che abbraccia nuovi inizi.\n\nE il loro viaggio contro l'ignoto intraprenderà un nuovo punto di partenza.\n\n"
  },
  CollectionHall_49015_Title = {
    Text = "Primavera a Yakutsk"
  },
  CollectionHall_49018_Desc = {
    Text = "A.F. 314, in una notte di pieno inverno, il fragore di un'esplosione echeggiò attraverso l'Akutlin.\n\nLa terra tremò e i boschi si illuminarono come in pieno giorno.\nAccompagnato dalle grida della vita e dai lamenti della natura, il villaggio fu raso al suolo.\n\nSecondo Dexter, una Studente pre-universitaria nel sistema Awaken che partecipò all'\"Indagine sul disastro di Akut,\" tra le fiamme che si levavano verso il cielo quella notte, colori di nero e argento brillavano intensamente."
  },
