  CollectionHall_51019_Desc = {
    Text = "<Title:Data di fondazione>\nPrima del Diluvio\n\n<Title:Fondatore>\nSconosciuto\n\n<Title:Panoramica>\nUn popolo nomade che si separò dall'Impero Assiro.\nCelati tra le violente tempeste del Deserto di Remouahe, vivono in modo molto primitivo, comunicando raramente con gli estranei. Gli Aramiti venerano l'\"Albero Madre dell'Abbondanza\", affidandosi alle sue straordinarie capacità riproduttive e all'Acqua del fiume sacro per mantenere la propria popolazione.\nDopo l'\"Incidente di Remouahe\", gli Aramiti svanirono senza lasciare traccia, senza ulteriori notizie."
  },
