  },
  CollectionHall_71013_Desc = {
    Text = "Riguardo alla Ricerca sull'Argento, Spiriti del Risveglio evocati dalle alte sfere.\nQuesta è l'ultima speranza dell'Umanità dopo l'Avvento della Dissoluzione."
  },
  CollectionHall_71013_Title = {Text = "Risveglio"},
  CollectionHall_71014_Desc = {
    Text = "I Passi della notte inseguono l'esploratore — quell'Ombra si allunga sempre più nel reame dalla luce fioca."
  },
  CollectionHall_71014_Title = {Text = "Morimens"},
  CollectionHall_71015_Desc = {
    Text = "I pionieri tracciano il sentiero, e i loro successori ne portano avanti la fiaccola. Gli strumenti d'argento non si offuscano mai, e la sacra ricerca del Mito non cesserà mai."
  },
  CollectionHall_71015_Title = {
    Text = "Il cimelio del Cercatore"
