  },
  CollectionHall_71016_Title = {
    Text = "Ex Oblivione"
  },
  CollectionHall_71017_Desc = {
    Text = "Denso liquido nero, una marea del tempo stesso, corrode realtà e percezione. Dove scorre la sua storia, memoria ed esistenza si tramutano in vuoto."
