  },
  CollectionHall_71028_Desc = {
    Text = "Il Museo delle Cere ha tre regole: primo, non toccare le sculture di cera; secondo, non rimuovere i loro rivestimenti; terzo, non far gocciolare sangue nel Museo delle Cere. Qualunque cosa facciate, vi prego, non violatele mai, per nessuna ragione."
