  },
  CollectionHall_89348_Title = {
    Text = "Il Regno Eterno"
  },
  CollectionHall_89349_Desc = {
    Text = "Abbandono e Tradimento sono comuni tra i potenti; non esponete loro la schiena, per non diventare l'ultima luce e l'ultimo calore."
  },
  CollectionHall_89349_LockTip = {
    Text = "Completa Livello Difficile 3-10"
  },
  CollectionHall_89349_Title = {
    Text = "Gli abbandonati"
  },
  CollectionHall_89350_Desc = {
    Text = "La sua anima è dietro di te, e tu solo sei l'unico muro in questo istante, mentre l'impotenza del destino ti stringe in una morsa; non puoi cambiare quel finale.\nIl finale in cui lei viene sommersa dalla Marea nera."
  },
  CollectionHall_89350_LockTip = {
    Text = "Completa l'Immersione Psichica \"Nucleo Distorto\""
  },
  CollectionHall_89350_Title = {
    Text = "Salvataggio Solitario"
  },
  CollectionHall_89351_Desc = {
    Text = "Un sussurro si avvolge al tuo orecchio, mormorando in un silenzio senza fine.\nTi sforzi di cogliere le parole — ma quando lo stesso suono inizia a riecheggiare dall'interno del tuo cranio, comprendi: sono le ali di un milione di insetti che battono in perfetta, intima armonia: Fzzzt — fzzzt — torna a casa, torna a casa."
  },
  CollectionHall_89351_LockTip = {
    Text = "Completa Capitolo Astrale 2-18"
  },
  CollectionHall_89351_Title = {
    Text = "Sussurro di un milione di ali"
  },
  CollectionHall_89352_Desc = {
    Text = "Nei momenti cruciali della vita, sembra sempre che vi sia una pioggerellina sottile ad accompagnarli.\nDì addio a quelle memorie tra la pioggia fine, seppellendo il vino amaro nel profondo del cuore, stringi la Chiave d'Argento nella mano e intraprendi un nuovo viaggio.\nChe la Chiave d'Argento ci Guidi."
  },
  CollectionHall_89352_LockTip = {
    Text = "Completa Capitolo Astrale Difficile 1-10"
  },
  CollectionHall_89352_Title = {
    Text = "Addio del Maestrale"
  },
  CollectionHall_89353_Desc = {
    Text = "Il caldo sole primaverile, il palazzo da sogno, gli abiti volteggianti, il ballo colmo di risate e la bella e gentile principessa.\nQuesto è tutto ciò che i cavalieri desiderano proteggere."
  },
  CollectionHall_89353_LockTip = {
    Text = "Completa l'Immersione Psichica \"Il Desiderio del Cavaliere\""
  },
  CollectionHall_89353_Title = {
    Text = "Festino di Primavera a Corte"
  },
  CollectionHall_89354_Desc = {
    Text = "Sangue, massacri, mutamenti... sepolti sotto l'infinita sabbia gialla giacciono una storia crudele e comune nel fiume del tempo."
  },
  CollectionHall_89354_LockTip = {
    Text = "Completa l'Immersione Psichica \"Discendente Pallido\" a difficoltà ardua"
  },
  CollectionHall_89354_Title = {
    Text = "Sotto le Sabbie"
  },
  CollectionHall_89355_Desc = {
    Text = "Quando non sai come rispondere, fai semplicemente la carina, ah hey~"
  },
  CollectionHall_89355_LockTip = {
    Text = "Completa Livello 3-14"
  },
  CollectionHall_89355_Title = {Text = "Ehe!"},
  CollectionHall_89356_Desc = {
