  CollectionHall_89366_Title = {
    Text = "Il Santo Pallido"
  },
  CollectionHall_89367_Desc = {
    Text = "Le maree si alzano, gli Stridi echeggiano, dolorose Memorie emergono come un'Ondata, dilaniando lo Spirito della ragazza. Le lacrime nere che scorrono dai Suoi Occhi sono le sue silenziose grida d'aiuto."
