  CollectionHall_89370_Title = {
    Text = "Lapidi Viscide"
  },
  CollectionHall_89371_Desc = {
    Text = "Fragranze eleganti, una miriade di Beni, ma quanti possono permettersi il prezzo fissato da Lady Daffodil?"
