  CollectionHall_89371_Title = {
    Text = "Il Cottage di Daffodil"
  },
  CollectionHall_89372_Desc = {
    Text = "Mani calde accarezzano dolcemente la testa della ragazza, placando il suo cuore inquieto."
  },
  CollectionHall_89372_LockTip = {
    Text = "Completa Livello 3-14"
  },
  CollectionHall_89372_Title = {
    Text = "Non temere, sono qui"
  },
  CollectionHall_89373_Desc = {
    Text = "Il tempo ulula, il tempo ruggisce, il tempo insegue coloro che hanno fallito tre volte. Non tentate di fuggire, poiché l'esito è già predeterminato."
  },
  CollectionHall_89373_LockTip = {
    Text = "Completa Livello Difficile 4-12"
  },
  CollectionHall_89373_Title = {
    Text = "Mostro di Causa ed Effetto"
  },
  CollectionHall_89374_Desc = {
    Text = "Il giudizio non si arresterà; il giudizio deve essere eseguito.\nMostri nascono dal riflesso, con la propria carne e il proprio sangue come stoppino, propagando il fuoco della purificazione per il mondo intero."
  },
  CollectionHall_89374_LockTip = {
    Text = "Completa il registro speciale \"Colore del Sangue\" a difficoltà Difficile"
  },
  CollectionHall_89374_Title = {
    Text = "Carne e Fiamma"
  },
  CollectionHall_89375_Desc = {
    Text = "Quando posizioni e volontà si scontrano, gli esseri umani spesso credono soltanto nei propri principi.\nPer la maggior parte delle persone, ciò in cui credono è l'unica giustizia."
  },
  CollectionHall_89375_LockTip = {
    Text = "Completa Livello 4-16"
  },
  CollectionHall_89375_Title = {
    Text = "Giustizia Contrapposta"
  },
  CollectionHall_89376_Desc = {
    Text = "L'incontro giunse troppo presto, la verità giunse troppo tardi, l'anima frantumata e lacerata dalla cruda realtà sta lentamente guarendo tra le sue piccole mani.  \nI due che si rincorrevano tra vento e neve infine si abbracciano e piangono nella fessura che trascende il tempo."
  },
  CollectionHall_89376_LockTip = {
    Text = "Completa Livello 4-16"
  },
  CollectionHall_89376_Title = {
    Text = "Una Riunione Inattesa"
  },
  CollectionHall_89377_Desc = {
    Text = "Una signora deve sempre mantenere l'eleganza! \nNaturalmente, intendo dire che qualsiasi cosa faccia una signora è elegante!"
  },
  CollectionHall_89377_LockTip = {
    Text = "Completa Livello 5-15"
  },
  CollectionHall_89377_Title = {
    Text = "Signora dell'Abisso"
  },
  CollectionHall_89378_Desc = {
    Text = "Il focolare caldo accoglie ogni Ospite. Ma attenzione, la notte ha cani feroci; non uscite fuori."
  },
  CollectionHall_89378_LockTip = {
    Text = "Completa Livello 3-14"
  },
  CollectionHall_89378_Title = {
    Text = "Un paese nella Neve"
  },
  CollectionHall_89379_Desc = {
    Text = [[
Dietro questa porta, capace persino di imprigionare il tempo, si cela l'ultima scelta di una madre per proteggere la sua amata figlia. 
"Ti amo, Lily."]]
  },
  CollectionHall_89379_LockTip = {
    Text = "Completa Livello Difficile 4-12"
  },
  CollectionHall_89379_Title = {
    Text = "Prigione Eterna"
  },
  CollectionHall_89380_Desc = {
    Text = "La Caccia, una fuggitiva, un amore materno pietrificato, e un abbraccio oltre la vita e la morte."
