  },
  CollectionHall_89385_Title = {
    Text = "Follia ossessiva"
  },
  CollectionHall_89386_Desc = {
    Text = "Guarda, la Luna Cremisi è sorta, e tutti i peccatori saranno purificati."
  },
  CollectionHall_89386_LockTip = {
    Text = "Completa il registro speciale \"Colore del Sangue\""
  },
  CollectionHall_89386_Title = {
    Text = "Luna di Sangue"
  },
  CollectionHall_89387_Desc = {
    Text = "Padre Misericordioso, brucerò la mia carne d'ossa, incenerirò la mia anima, per servire da esca alla \"fiamma pallida\".\nTi prego, riversa ogni sofferenza su di me, affinché quei fanciulli smarriti possano proseguire il loro cammino."
  },
  CollectionHall_89387_LockTip = {
    Text = "Completa il registro speciale \"Colore del Sangue\" a difficoltà Difficile"
  },
  CollectionHall_89387_Title = {
    Text = "Rituale della Pioggia di Serpenti"
  },
  CollectionHall_89388_Desc = {
    Text = "La Lanterna scaccerà ogni male.\nDevi pentirti devotamente, versare ogni goccia di sangue, per mondare i peccati e ascendere al cielo."
  },
  CollectionHall_89388_LockTip = {
    Text = "Completa il registro speciale \"Colore del Sangue\""
  },
  CollectionHall_89388_Title = {
    Text = "Lanterna Eterna"
  },
  CollectionHall_89389_Desc = {
    Text = [[
Me lo avete promesso, tutti voi me lo avete promesso. 
Se non posso salvare Lemuria, allora andiamo insieme e seppelliamoci con essa!]]
  },
