    Text = "Completa Livello Difficile 5-10"
  },
  CollectionHall_89392_Title = {
    Text = "Sfida alla Profezia"
  },
  CollectionHall_89393_Desc = {
    Text = "Ti riporterò indietro, indietro a incontrare il \"padrone\", solo così..."
  },
  CollectionHall_89393_LockTip = {
    Text = "Completa Livello 3-14"
  },
  CollectionHall_89393_Title = {
    Text = "Legami di Sangue"
  },
  CollectionHall_89394_Desc = {
    Text = "Il tuo nemico non è uno, ma molti. Un coro di anime concatenate, che tirano, resistono, chiamano. Deponi il tuo inutile io. Lascia che la tua mente cieca e ostinata si unisca al collettivo che non ha mai conosciuto la solitudine."
  },
  CollectionHall_89394_LockTip = {
    Text = "Completa Capitolo Astrale Difficile 2-12"
  },
  CollectionHall_89394_Title = {
    Text = "Volontà dell'Alveare"
  },
  CollectionHall_89395_Desc = {
