  },
  CollectionHall_89395_LockTip = {
    Text = "Completa il registro speciale \"Colore del Sangue\""
  },
  CollectionHall_89395_Title = {
    Text = "Benevolenza Disinteressata"
  },
  CollectionHall_89396_Desc = {
    Text = [[
Prendi la mia mano. Accetta il fiore che non appassisce mai, colto dalla memoria.
Non voltarti indietro. Arriveremo infine, dinanzi al lucente portale d'argento.]]
