  },
  CollectionHall_89412_Desc = {
    Text = "Chi un tempo ti stava dinanzi ora ti segue alle spalle.\nEppure tu credi: se corri con tutto ciò che sei, allora in attesa alla fine del tempo stesso vi saranno quelle mani familiari e calde."
