  },
  CollectionHall_89414_Desc = {
    Text = "Gli eroi e la principessa corrono sotto il cielo notturno, la ghiaia sotto i loro piedi racconta la gioia di vivere. Quel cuore, sigillato per mille anni, lentamente riprende a battere col passaggio di una stella cadente."
  },
  CollectionHall_89414_LockTip = {
