  CollectionHall_89414_Title = {
    Text = "Pioggia di Meteore per Due"
  },
  CollectionHall_89415_Desc = {
    Text = "Non occorre che tu parli. Nell'istante in cui giungi, il più sincero aiuto ti troverà.\nUna guida sorridente ha già teso la mano — ti condurrà nei grovigli della tua stessa anima, più in profondità di quanto tu abbia mai osato guardare."
  },
  CollectionHall_89415_LockTip = {
