  },
  CollectionHall_89415_Title = {Text = "La Mente"},
  CollectionHall_89416_Desc = {
    Text = "Quando il primo raggio di luce mattutina penetrò nel Labirinto, la Principessa degli Aracnidi, che aveva dormito per mille anni, accolse il suo ultimo Accolito."
