  CollectionHall_89420_Title = {
    Text = "Re nell'Abisso"
  },
  CollectionHall_89706_Desc = {
    Text = "Orfana di origini sconosciute, Corposant fu accolta dai membri di un equipaggio fin dai suoi primi ricordi e visse a bordo di una nave.\nGrazie a questa esperienza, Corposant ha nutrito fin dall'infanzia un profondo desiderio e una grande curiosità per il Mare Profondo.\nCrescendo, scelse naturalmente una carriera legata al Mare Profondo e alle navi: pilota.\nDa quel momento, la fanciulla che ama il Mare Profondo avrebbe vagato eternamente sulle onde, guidando le navi sotto una volta di stelle.\nÈ \"nata\" sul mare, sulla nave.\nE non teme la \"morte\" sul mare, sulla sua nave.\nÈ così che è destinata a vivere."
  },
  CollectionHall_89706_LockTip = {
    Text = "Risveglia \"Corposant\""
  },
  CollectionHall_89706_Title = {Text = "Corposant"},
  CollectionHall_89968_Desc = {
    Text = "Massacro, Odio, Follia e dolore; il campo di battaglia non ne è mai privo. Quando scommetti la tua vita al tavolo da poker del Mostro, dovresti chiederti quale vortice Cremisi ne scaturirà."
  },
  CollectionHall_89968_LockTip = {
    Text = "Completa l'Immersione Psichica \"Sangue e Sabbia\""
  },
  CollectionHall_89968_Title = {
    Text = "Trappola Cremisi"
  },
  CollectionHall_89969_Desc = {
    Text = "Secondo la leggenda, la navigatrice si trasformerà in un lampo bianco e azzurro sopra l'albero maestro dopo la morte, continuando a guidare il viaggio della nave.\nQuando ha dato fuoco alla propria vita in cima all'albero maestro, ha forse scorto Il Sentiero della speranza che ritornava?"
  },
  CollectionHall_89969_LockTip = {
    Text = "Completa la peregrinazione della coscienza \"L'Ultima Navigazione\""
  },
  CollectionHall_89969_Title = {
    Text = "Fuoco di Sant'Elmo"
  },
  CollectionHall_89970_Desc = {
    Text = "Nacque in un destino di odio, sangue versato e conflitto senza fine. Quando abbandonò ogni tenera illusione e scelse di impugnare coltello e pistola, il canto trionfale del fato aveva già iniziato a risuonare per lei. Era destinata a diventare una guerriera, a lavare il suo odio col sangue dei nemici, per poi vivere un'esistenza forse priva di gloria, ma impavida e senza rimpianti."
  },
  CollectionHall_89970_LockTip = {
    Text = "Completa il registro speciale \"Il Reduce di Elworth\""
  },
  CollectionHall_89970_Title = {
    Text = "Vendetta in Cremisi"
  },
  CollectionHall_89971_Desc = {
    Text = "Sotto il sole al tramonto rosso sangue giace sabbia gialla intrisa di sangue.\nIl guerriero più forte si erge sul campo di battaglia prossimo a sprofondare nella notte, rievocando le fiamme dorate e la gloria di un tempo.\nInnumerevoli avvoltoi urlanti si levano in volo, oscurando gli ultimi raggi di sole. Nella grande spedizione d'oriente, il deserto è colmo di non-morti, che lo accompagnano nella sua sepoltura."
  },
  CollectionHall_89971_LockTip = {
    Text = "Completa l'Immersione Psichica \"Sangue e Sabbia\" a difficoltà ardua"
  },
  CollectionHall_89971_Title = {
    Text = "Tramonto Insanguinato"
  },
  CollectionHall_89972_Desc = {
    Text = "Se questo mondo è sprofondato nell'Oscurità, allora io sarò l'ultima torcia.\nSe non vi è più Giustizia tra La Folla, allora io parlerò per i più deboli."
  },
  CollectionHall_89972_LockTip = {
    Text = "Completa la peregrinazione della coscienza \"L'Ultima Navigazione\""
  },
  CollectionHall_89972_Title = {
    Text = "Faro nella Notte Infinita"
  },
  CollectionHall_89973_Desc = {
    Text = "Quella era la sua battaglia predestinata, il campo di battaglia a cui doveva giungere.\nSi scrollò di dosso ogni debolezza, esitazione e paura del passato.\nNon ha rimpianti, poiché ha compreso il vero significato del combattere in questa vita.\nNon è sola; la lama nella sua mano riflette il volto selvaggio di un'altra sé."
  },
  CollectionHall_89973_LockTip = {
    Text = "Completa il record speciale \"Il Reduce di Elworth\" in difficoltà Difficile"
  },
  CollectionHall_89973_Title = {
    Text = "Domanda alla Catena Montuosa"
  },
  CollectionHall_89974_Desc = {
    Text = "Hey ho, hey ho, levate l'àncora, issate le vele, sciogliete l'ultima cima.\nLa nostra navigatrice si è arrampicata sull'albero maestro, e la bandiera variopinta sventola in alto.\nSpiega le Vele, Spiega le Vele, nella direzione che lei indica, noi salperemo!"
  },
  CollectionHall_89974_LockTip = {
    Text = "Completa la peregrinazione della coscienza \"L'Ultima Navigazione\""
  },
  CollectionHall_89974_Title = {
    Text = "Diario del Navigatore"
  },
  CollectionHall_89975_Desc = {
    Text = "Ogni volta che salpa, è preparata con l'ultimo testamento.\nIl canto tramandato di generazione in generazione agisce come una ninnananna in un sogno, abbracciando dolcemente la sua anima.\nLe bandiere luminose sventolano nel vento; la sua carne potrà crollare, marcire o sprofondare nel mare profondo, ma la sua anima starà sicuramente ritta sulla sua nave, irradiando luce eterna verso le stelle e il mare."
  },
  CollectionHall_89975_LockTip = {
    Text = "Completa la peregrinazione della coscienza \"L'Ultima Navigazione\""
  },
  CollectionHall_89975_Title = {
    Text = "Lamento del Navigatore"
  },
  CollectionHall_89976_Desc = {
    Text = [[
Nel deserto, il vento e la sabbia sono ospiti implacabili: la polvere vorticosa riempie bocche e narici dei vivi, e seppellisce i morti senza nome.
Solo le bestie che bramano la carne cercano delicatamente nel vento il dolce festino.]]
  },
  CollectionHall_89976_LockTip = {
    Text = "Completa l'Immersione Psichica \"Sangue e Sabbia\""
  },
  CollectionHall_89976_Title = {
    Text = "Bestia delle Sabbie Gialle"
  },
  CollectionHall_89977_Desc = {
    Text = "Il sole del deserto non somiglia a nessun altro — pallido, abbagliante e feroce, non mostra mai un lato gentile. Una bestia che conosce solo la sua luce rovente non può immaginare il tiepido sole primaverile che descrivi. Va' dunque, va', e trova per lui quel sole gentile."
  },
  CollectionHall_89977_LockTip = {
    Text = "Completa l'Immersione Psichica \"Sangue e Sabbia\""
  },
  CollectionHall_89977_Title = {
    Text = "Sangue e Sabbia senza Ritorno"
  },
  CollectionHall_89978_Desc = {
    Text = "Neve infinita cade, danzando nell'aria, coprendo di brina i capelli dei guerrieri.\nIn questo istante, le Memorie della sua vita scorrono; ella cammina dalle sottili profondità dei cuori umani, dirigendosi verso l'imponente Catena Montuosa.\nTradimento, abbandono e protezione, tutto il dolore e la rabbia non sono che una serie di Battaglie. Con le persone, con le montagne, e con sé stessi.\nGuarda il suo comandante, i nuovi compagni sconosciuti eppure familiari, e abbozza un sorriso impacciato.\nUn giorno forse trionferà, o forse cadrà per sempre sul campo di battaglia, ma persino nell'istante in cui ascenderà al cielo o precipiterà negli inferi, non lascerà la lama che stringe in pugno.\nPer non perdere tutto ancora una volta, questa volta sceglie di levare la spada della protezione prima di cercare vendetta, avanzando sola verso il suo campo di battaglia."
  },
  CollectionHall_89978_LockTip = {
    Text = "Completa il registro speciale \"Il Reduce di Elworth\""
  },
  CollectionHall_89978_Title = {
    Text = "Per il Domani Promesso"
  },
  CollectionHall_89998_LockTip = {
    Text = "Completamento Evento: \"Ombra che Spia il Regno Divino: Marea Desolata\""
  },
  CollectionHall_89998_Title = {
    Text = "L'ombra che incombe sul Reame Divino: Marea Anomala"
  },
  CollectionHall_89999_LockTip = {
    Text = "Completamento Evento: \"Prigioniero riflesso: Spirito Celeste\""
  },
  CollectionHall_89999_Title = {
    Text = "Prigioniero riflesso: Spirito Celeste"
  },
  CollectionHall_90245_LockTip = {
    Text = "Completa un qualsiasi livello in Paesaggio Onirico: \"Oltre i cieli: Parte I\""
  },
  CollectionHall_90245_Title = {
    Text = "Prima che l'Uccello Cada"
  },
  CollectionHall_90415_Title = {
    Text = "Oltre i cieli: Parte I"
  },
  CollectionHall_90416_Desc = {
    Text = "Uno di una serie di esperimenti coltivati dalla Chiesa della luce del tempio, sopravvissuto fortunosamente all'essere scartato nel cumulo di rifiuti grazie al fatto di essere nato come gemello.\nCresciuto insieme al fratello minore Pollux come Divus fin dall'infanzia, fu sottoposto a una rigida disciplina e costantemente indottrinato con la teologia della Chiesa della luce del tempio. L'unico contatto con il mondo esterno era un manoscritto pesante e splendidamente realizzato, offerto da un fedele.\nDa giovane, dopo che il fratello fu sottoposto a un crudele rituale di trasformazione da parte della Chiesa, i due decisero di fuggire insieme in cerca di libertà, ma furono rapidamente ricatturati.\nFu immerso nella vasca di Dissoluzione nota come la \"Vasca del Peccato\", dove il Rito di Cancellazione del Peccato fu usato per guarire le sue ferite, costringendolo a sopportare un tormento prolungato.\nAlla fine, fu dimenticato da tutti tranne che da Juliette—incluso Pollux—e il rapporto con il fratello divenne teso.\nDa allora, è rimasto in uno stato di dormienza, fingendo esteriormente obbedienza alla Chiesa senza mai abbandonare l'ossessione di fuggire di nuovo con il fratello, attendendo pazientemente un'altra occasione per riconquistare la libertà."
  },
  CollectionHall_90416_LockTip = {
    Text = "Risveglia \"Castor\""
  },
  CollectionHall_90416_Title = {Text = "Castor"},
  CollectionHall_94552_LockTip = {
    Text = "Completa Evento: \"La Grande Conquista: Predazione Sacra\""
  },
  CollectionHall_94552_Title = {
    Text = "La Grande Conquista: Predazione Sacra"
  },
  CollectionHall_94553_Desc = {
    Text = "Pollux era uno dei soggetti sperimentali gemelli artificiali creati dalla Chiesa della luce del tempio per un rituale di incarnazione divina. Proprio quando furono giudicati dei fallimenti e stavano per essere eliminati senza pietà, Pollux nacque miracolosamente, separandosi dalla carne e dal sangue del fratello.\nQuesto feroce e disperato attaccamento alla vita non fu una benedizione. Non fece altro che mutare il loro destino da una tragedia di breve durata a una ben più prolungata.\nForse a causa del mistero della loro natura gemellare, il suo incarnato e la sua personalità erano l'esatto opposto di quelli del fratello. Essendo il gemello più vivace e sveglio, si dedicava costantemente a comportamenti dispettosi che sfidavano la rigida indottrinazione a cui erano sottoposti, proprio come un bambino monello in una famiglia normale... almeno finché non fu selezionato come ricettacolo del divino e sottoposto a regolari, dolorosi e sanguinosi rituali di \"Trasformazione Divina\".\nIncapace di sopportare quel destino agonizzante e senza speranza, supplicò e complottò con il fratello. Nel corso di diversi anni, usarono un codice segreto per pianificare la fuga e infine riuscirono a superare innumerevoli ostacoli.\nTuttavia, la loro libertà fu di breve durata. Furono presto catturati dagli inseguitori della Chiesa. Juliette ordinò che le sue ali di libertà venissero tarpate e fu sottoposto a un lavaggio del cervello estremo. Questo alla fine lo portò a dimenticare completamente il fratello e a godere invece della sensazione di essere una figura venerata, un Divus.\nDopo la sua seconda fuga, Pollux recuperò i ricordi grazie alla morte del fratello e agli effetti del rituale di incarnazione. Il suo \"Sacro Cuore\" fu acceso dall'odio e dalla rabbia, e la sua vita prese una nuova direzione: affrontare e distruggere la Chiesa della luce del tempio."
  },
  CollectionHall_94553_LockTip = {
    Text = "Completa il Paesaggio Onirico \"Oltre l'orizzonte: II\""
  },
  CollectionHall_94553_Title = {Text = "Pollux"},
  CollectionHall_95436_Desc = {
    Text = "Su, sempre più su, l'uccello lottava, le ali che battevano contro il peso crudele del mondo, ogni affondo disperato che lo portava più in alto, nell'abbraccio della tempesta.\nEppure non sapeva che un filo invisibile era sempre stato legato alla sua zampa. Persino in volo, non era che un patetico aquilone.\nE ora, il filo si stava tendendo."
  },
  CollectionHall_95436_LockTip = {
    Text = "Completa il Paesaggio Onirico \"Oltre l'Orizzonte: Parte Superiore\""
  },
  CollectionHall_95436_Title = {
    Text = "Un Aquilone Pietoso"
  },
  CollectionHall_95437_Desc = {
    Text = "Hai visto quel volto — dolce, sereno, di una bellezza insostenibile."
  },
  CollectionHall_95437_LockTip = {
    Text = "Completa il registro speciale \"Ombra della Città della Pioggia\""
  },
  CollectionHall_95437_Title = {
    Text = "Nel Profondo del Velo di Pioggia"
  },
  CollectionHall_95438_Desc = {
    Text = "Essere un gatto, solo un gatto, accoccolata su grembi scaldati dal sole. Restare sempre accanto alla sua amata, rannicchiata nella luce del sole.\nNessuna ombra, nessuna voce, solo amore e la sicurezza dell'essere piccola. Ma i sogni sono vetro, e il vetro è fatto per infrangersi."
  },
  CollectionHall_95438_LockTip = {
    Text = "Completa il registro speciale \"Scissione Tranquilla\""
  },
  CollectionHall_95438_Title = {
    Text = "L'Unico Desiderio del Gatto"
  },
  CollectionHall_95439_Desc = {
    Text = "Anche se il mondo si riduce in cenere, anche se tutto viene dissolto nella D-melma, la medusa Innocente può eternamente immergersi nei propri sogni.\nLà dentro, tutto è come era. Solo risate. Solo gioia."
  },
  CollectionHall_95439_LockTip = {
    Text = "Completa l'Immersione Psichica \"Eadem Omnia\" a difficoltà ardua"
  },
  CollectionHall_95439_Title = {
    Text = "Sprofondando in Marcio Piacere"
  },
  CollectionHall_95440_Desc = {
    Text = "Gli inverni di Londinium erano avari di neve, così quando cadeva, faceva turbinare i Fanciulli in vortici estasiati di muffole e risate.\nTi svegliasti da un sogno lungo quanto un secolo, allungasti la mano oltre la finestra e catturasti un singolo fiocco. Soddisfatto, si sciolse contro il calore della tua pelle.\nLa neve fluttuava verso terra, tornando ai fiumi nascosti, alla quieta Oscurità dove tutte le acque ricordano di essere una sola.\nE nella prima vera tempesta di quell'anno, un'altra di \"lei\" fece Ritorno a casa.\nDolci sogni, fiocco di neve. Dolci sogni, \"24.\""
  },
  CollectionHall_95440_LockTip = {
    Text = "Completa il registro speciale \"Scissione Tranquilla\""
  },
  CollectionHall_95440_Title = {
    Text = "Sogni d'Oro, Fiocco di Neve"
  },
  CollectionHall_95441_Desc = {
    Text = "Rami di corallo bianco si attorcono in guglie svettanti, generando un palazzo di pallido splendore osseo.\nTra le sue colonne deformi, pesci prismatici intrecciano la loro danza senza fine.\nIl tuo corpo sprofonda. Il tuo Spirito fluttua.\nCedi il respiro volontariamente, annegando, annegando... Annegando con lei in questo madreperlaceo Delirium.\nÈ il Miracolo dell'oceano. È la tua calda, azzurra Terra dei Bianchi Uccelli."
  },
  CollectionHall_95441_LockTip = {
    Text = "Completa l'Immersione Psichica \"Scultura Melodica\""
  },
  CollectionHall_95441_Title = {
    Text = "Il Palazzo d'Alabastro"
  },
  CollectionHall_95442_Desc = {
    Text = "Din din—— Il trenino parte!\nLasciate che porti i miei amici nel regno eterno di fiabe gioiose, senza dolore."
  },
  CollectionHall_95442_LockTip = {
    Text = "Completa l'Immersione Psichica \"Eadem Omnia\""
  },
  CollectionHall_95442_Title = {
    Text = "Delirium Infantile"
  },
  CollectionHall_95443_Desc = {
    Text = "È lei l'assassina? Assomiglia a un'amante che hai conosciuto in un'altra vita.\nAcqua piovana, foglie morte e il profumo narcotico di fiori che sbocciano nella notte. Inspiri profondamente, cercando nell'aria umida la prova del suo crimine, quell'odore di rame. Non ce n'è traccia.\nLei non offre spiegazioni. La nebbia si addensa, e tu sprofondi nel suo sogno cinereo."
  },
  CollectionHall_95443_LockTip = {
    Text = "Completa il registro speciale \"Ombra della Città della Pioggia\""
  },
  CollectionHall_95443_Title = {
    Text = "Il Sospettato"
  },
  CollectionHall_95444_Desc = {
    Text = "Ora conosci la fame che lei un tempo ha sopportato.\nFerina. Solitaria. Incapace di comprendere.\nLei è fortunata: il suo lungo vagare è finito. Stringe memorie calde come ossa da rosicchiare per l'eternità.\nOra prende i suoi consanguinei per mano, guidando quest'anima perduta e tremante nella quieta oscurità dei sogni."
  },
  CollectionHall_95444_LockTip = {
    Text = "Completa il registro speciale \"L'Ombra della Città della Pioggia\" a difficoltà Difficile"
  },
  CollectionHall_95444_Title = {
    Text = "Il Sogno di una Bestia"
  },
  CollectionHall_95445_Desc = {
    Text = "Il coltello era mio. La mano che lo impugnava, mia. Il cuore che ha trafitto? Anch'esso mio.\nIl destino è uno scriba spietato, e la vita ne inchiostro le pagine d'amarezza. Io sono piccola sotto di esse. Debole. Tremante.\n<Italic:Perché sono me? Sono stata me stessa nel modo giusto?>\nLe domande si avvolgono come fumo, ma il riflesso rifiuta ogni risposta."
  },
  CollectionHall_95445_LockTip = {
    Text = "Completa il registro speciale \"Scissione Tranquilla\""
  },
  CollectionHall_95445_Title = {Text = "Rispondimi"},
  CollectionHall_95446_Desc = {
    Text = "<Italic:«Oh? Sembri... diversa, adesso.»>\nIl tuo sguardo si è fatto più luminoso? I tuoi movimenti più vividi? O questo mediocre involucro ha accolto un'anima nuova?"
  },
  CollectionHall_95446_LockTip = {
    Text = "Completa l'Immersione Psichica \"Scultura Melodica\""
  },
  CollectionHall_95446_Title = {
    Text = "Trasferimento d'Anima"
  },
  CollectionHall_95447_Desc = {
    Text = "Che cada la neve, che pianga la pioggia, che arda il sole o che le nubi si addensino cupe — oggi, come ogni giorno, il fiume prosegue il suo cammino, silenzioso, imperturbabile."
  },
  CollectionHall_95447_LockTip = {
    Text = "Completa il registro speciale \"Scissione Tranquilla\""
  },
  CollectionHall_95447_Title = {
    Text = "Il fiume scorre ancora"
  },
  CollectionHall_95448_Desc = {
    Text = "La marea ruggisce. I teschi urlano.\nMille occhi si fissano su di te. Mille bocche maledicono il tuo nome.\nTi annegheranno. Ti divoreranno.\nStringi gli occhi per il terrore — e quando li riapri, ti circondano."
  },
  CollectionHall_95448_LockTip = {
    Text = "Completa il registro speciale \"Ombra della Città della Pioggia\""
  },
  CollectionHall_95448_Title = {
    Text = "Mare di Teschi"
  },
  CollectionHall_95449_Desc = {
    Text = "Ti ha promesso di portarti a casa. Insieme."
  },
  CollectionHall_95449_LockTip = {
    Text = "Completa l'Immersione Psichica \"Scultura Melodica\""
  },
  CollectionHall_95449_Title = {
    Text = "Arte della Corallizzazione"
  },
  CollectionHall_95450_Desc = {
    Text = "Quell'illustre Ospite un tempo osservò la schiena piena di speranza di Castor sotto il chiaro di luna, sussurrando sommessamente una profezia:\"Camminerà fuori, e lotterà disperatamente nella tempesta. Eppure ciò che lo solleverà in volo sarà anche ciò che lo farà precipitare.\""
  },
  CollectionHall_95450_LockTip = {
    Text = "Completa il Paesaggio Onirico \"Oltre l'Orizzonte: Parte Superiore\""
  },
  CollectionHall_95450_Title = {
    Text = "Occhio della Tempesta"
  },
  CollectionHall_95451_Desc = {
    Text = "Nata dalla bellezza. Perfezionata nella morte.\nÈ genio, folle, demonio. Il boia le cui mani ti cullano il volto come quelle di una madre.\nIl suo amore bruciante ti preserva: un capolavoro impeccabile di carne.\nTi abbraccia, solleva le tue dita fredde come il marmo. Insieme farete Ritorno a casa, dove l'arte regna in eterno."
  },
  CollectionHall_95451_LockTip = {
    Text = "Completa l'Immersione Psichica \"Scultura Melodica\" in difficoltà Difficile"
  },
  CollectionHall_95451_Title = {
    Text = "Morte per Bellezza"
  },
  CollectionHall_95452_Desc = {
    Text = "L'oceano ha udito il mio richiamo, portandoti così al mio fianco.\nDa allora, abbiamo parlato, giocato e gioito liberamente, destinati a diventare i migliori amici del mondo.\nIn questa città colma di Dissoluzione e silenzio mortale."
  },
  CollectionHall_95452_LockTip = {
    Text = "Completa l'Immersione Psichica \"Eadem Omnia\""
  },
  CollectionHall_95452_Title = {
    Text = "Diventiamo Tutti Amici!"
  },
  CollectionHall_95453_Desc = {
    Text = "Torna a casa, coraggiosa. Torna a casa, codarda. Ragazza astuta, bambina sciocca, guerriera e creatura fragile — ognuna di me, torna a casa, torna a casa.\nLasciate che ogni cuore in frantumi si dissolva: il gioioso, l'addolorato, il furioso, il sofferente, quello così terribilmente stanco.\nSiamo insieme.\nPer sempre e in eterno, restano insieme."
  },
  CollectionHall_95453_LockTip = {
    Text = "Completa il record speciale \"Scissione Tranquilla\" in difficoltà Difficile"
  },
  CollectionHall_95453_Title = {
    Text = "Ognuna di Lei"
  },
  CollectionHall_95454_Desc = {
    Text = "Il vuoto nella sua anima infranta può essere colmato solo dalla più innocente delle favole. Un giorno, dirà addio al dolore e farà ritorno alla gioiosa terra natale delle sue fiabe."
  },
  CollectionHall_95454_LockTip = {
    Text = "Completa l'Immersione Psichica \"Eadem Omnia\""
  },
  CollectionHall_95454_Title = {
    Text = "Innocente Fiaba dell'Orrore"
  },
  CollectionHall_95455_Desc = {
    Text = "I vicoli si attorcigliavano come serpenti nell'oscurità, stretti e soffocanti, i loro ciottoli intrisi degli echi dei crudeli capricci del destino. Ricongiungimenti, litigi, separazioni — persino violenza, crudeltà e omicidio.\nPer fortuna, il racconto odierno non è sfociato in quest'ultimo spargimento di sangue. Ma chi potrebbe affermare che i primi non abbiano condotto a una tragedia ben più profonda?"
  },
  CollectionHall_95455_LockTip = {
    Text = "Completa il Paesaggio Onirico \"Oltre l'Orizzonte: Parte Superiore\""
  },
  CollectionHall_95455_Title = {
    Text = "Il Vicolo Oscuro"
  },
  CollectionHall_95469_LockTip = {
    Text = "Riscatta le ricompense del Giorno 1 nell'Evento: \"Estate sotto il Sole Nero: Fiesta Estiva\""
  },
  CollectionHall_95469_Title = {
    Text = "Estate sotto il Sole Nero"
  },
  CollectionHall_95981_LockTip = {
    Text = "Completamento Evento: \"Estetica Necromantica: Banchetto d'Anime\""
  },
  CollectionHall_95981_Title = {
    Text = "Estetica Necromantica: Soulsfeast"
  },
